      http: {
        example:
          'curl https://api.increase.com/simulations/account_statements \\\n    -H \'Content-Type: application/json\' \\\n    -H "Authorization: Bearer $YOLKEN_INCREASE_TEST_API_KEY" \\\n    -d \'{\n          "account_id": "account_in71c4amph0vgo2qllky"\n        }\'',
      },
